<script>
  let ws, reconnectTimer;

  function addLog(msg) {
    const log = document.getElementById('log');
    const t = new Date().toLocaleTimeString('en-GB');
    const div = document.createElement('div');
    div.innerHTML = '<span class="time">[' + t + ']</span>' + msg;
    log.appendChild(div);
    log.scrollTop = log.scrollHeight;
    while (log.children.length > 50) log.removeChild(log.firstChild);
  }

  function connect() {
    ws = new WebSocket('ws://' + location.host + '/ws');

    ws.onopen = () => {
      addLog('WebSocket connected');
      clearTimeout(reconnectTimer);
    };

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if ('bt' in data) {
          const el = document.getElementById('bt-status');
          if (data.bt) {
            el.textContent = '✅ روشن';
            el.className = 'value on';
          } else {
            el.textContent = '⛔ خاموش';
            el.className = 'value off';
          }
        }
        if ('ip' in data)   document.getElementById('ip-addr').textContent = data.ip;
        if ('up' in data)   document.getElementById('uptime').textContent = data.up;
        if ('log' in data)  addLog(data.log);
      } catch (e) {
        addLog('Parse error: ' + e.message);
      }
    };

    ws.onclose = () => {
      addLog('WebSocket disconnected · retrying...');
      reconnectTimer = setTimeout(connect, 2000);
    };

    ws.onerror = () => addLog('WebSocket error');
  }

  function send(cmd) {
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(cmd);
    } else {
      addLog('Not connected');
    }
  }

  connect();
</script>
