// ================== توابع کمکی ==================
String formatUptime(unsigned long ms) {
  unsigned long s = ms / 1000;
  unsigned long h = s / 3600;
  unsigned long m = (s % 3600) / 60;
  unsigned long sec = s % 60;
  char buf[32];
  sprintf(buf, "%02lu:%02lu:%02lu", h, m, sec);
  return String(buf);
}

void broadcastStatus() {
  StaticJsonDocument<200> doc;
  doc["bt"] = btEnabled;
  doc["ip"] = WiFi.localIP().toString();
  doc["up"] = formatUptime(millis() - bootTime);
  String json;
  serializeJson(doc, json);
  ws.textAll(json);
}

void sendLog(const String& msg) {
  StaticJsonDocument<160> doc;
  doc["log"] = msg;
  String json;
  serializeJson(doc, json);
  ws.textAll(json);
}

// ================== WebSocket Handler ==================
void onWsEvent(AsyncWebSocket *server, AsyncWebSocketClient *client,
               AwsEventType type, void *arg, uint8_t *data, size_t len) {

  if (type == WS_EVT_CONNECT) {
    Serial.printf("[WS] Client #%u connected\n", client->id());
    StaticJsonDocument<200> doc;
    doc["bt"] = btEnabled;
    doc["ip"] = WiFi.localIP().toString();
    doc["up"] = formatUptime(millis() - bootTime);
    String json;
    serializeJson(doc, json);
    client->text(json);
  }
  else if (type == WS_EVT_DISCONNECT) {
    Serial.printf("[WS] Client #%u disconnected\n", client->id());
  }
  else if (type == WS_EVT_DATA) {
    AwsFrameInfo *info = (AwsFrameInfo*)arg;
    if (!(info->final && info->index == 0 && info->len == len
          && info->opcode == WS_TEXT)) return;

    data[len] = 0;
    String cmd = String((char*)data);
    cmd.trim();
    Serial.printf("[CMD] %s\n", cmd.c_str());

    if (cmd == "on" && !btEnabled) {
      SerialBT.begin("ESP32_Panel");
      btEnabled = true;
      sendLog("Bluetooth ON");
      Serial.println("[BT] ON");
    }
    else if (cmd == "off" && btEnabled) {
      SerialBT.end();
      btEnabled = false;
      sendLog("Bluetooth OFF");
      Serial.println("[BT] OFF");
    }
    else {
      sendLog("Unknown command: " + cmd);
    }

    broadcastStatus();
  }
}

// ================== Routes ==================
void handleRoot(AsyncWebServerRequest *request) {
  request->send_P(200, "text/html", index_html);
}

void handleNotFound(AsyncWebServerRequest *request) {
  request->send(404, "text/plain", "Not Found");
}

// ================== Setup ==================
void setup() {
  Serial.begin(115200);
  delay(800);
  bootTime = millis();

  Serial.println("\n=== ESP32 Async Control Panel ===");

  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid, password);
  Serial.print("Connecting to WiFi");

  int attempts = 0;
  while (WiFi.status() != WL_CONNECTED && attempts < 60) {
    delay(500);
    Serial.print(".");
    attempts++;
  }

  if (WiFi.status() == WL_CONNECTED) {
    Serial.println("\n[WiFi] Connected");
    Serial.print("[WiFi] IP: ");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("\n[WiFi] FAILED — running in offline mode");
  }

  ws.onEvent(onWsEvent);
  server.addHandler(&ws);
  server.on("/", HTTP_GET, handleRoot);
  server.onNotFound(handleNotFound);
  server.begin();

  Serial.println("[HTTP] Server started on port 80");
}

// ================== Loop ==================
void loop() {
  ws.cleanupClients();
  delay(5);
}
